export const LANDING_USE_CASES = {"source":{"legacy":"terminalsync-web/src/content/useCases.ts (existing landing catalog)","liveSearch":{"repository":"jmggaravito-sudo/terminal-sync","ref":"e04d25d9d63414452fcaa2760e483266e8231ebd","commit":"e04d25d9d63414452fcaa2760e483266e8231ebd","dataFile":"src/data/useCases.ts"}},"categories":[{"id":"clientes","es":"Conseguir más clientes","en":"Win more clients"},{"id":"marketing","es":"Marketing","en":"Marketing"},{"id":"atencion","es":"Atención al cliente","en":"Customer service"},{"id":"operaciones","es":"Operaciones","en":"Operations"},{"id":"rrhh","es":"Recursos Humanos","en":"Human Resources"},{"id":"finanzas","es":"Finanzas","en":"Finance"},{"id":"legal","es":"Legal","en":"Legal"},{"id":"ecommerce","es":"E-commerce","en":"E-commerce"},{"id":"software","es":"Automatización y Software","en":"Automation & Software"},{"id":"direccion","es":"Dirección y estrategia","en":"Strategy & leadership"},{"id":"continuidad","es":"Continuidad","en":"Continuity"},{"id":"market","es":"Mercado y competencia","en":"Market & competitors"}],"cases":[{"id":"propuesta","area":"clientes","es":{"t":"Crear propuesta comercial","d":"Genera una propuesta profesional lista para enviar a un cliente.","p":"Ayúdame a crear una propuesta comercial para mi empresa.\n\nMi empresa vende: [describir tu producto o servicio].\nMi cliente ideal es: [tipo de cliente].\nEl objetivo de la propuesta es: [cerrar venta / agendar reunión / firmar contrato].\n\nIncluye: resumen ejecutivo, propuesta de valor, alcance del servicio, beneficios, precio sugerido, condiciones y próximos pasos."},"en":{"t":"Create a business proposal","d":"Generate a professional proposal ready to send to a client.","p":"Help me create a business proposal for my company.\n\nMy company sells: [describe your product or service].\nMy ideal client is: [type of client].\nThe goal of the proposal is: [close a sale / book a meeting / sign a contract].\n\nInclude: executive summary, value proposition, scope of service, benefits, suggested price, terms and next steps."}},{"id":"reunion-ventas","area":"clientes","es":{"t":"Preparar una reunión de ventas","d":"Te llega un guion con preguntas clave y objeciones esperadas.","p":"Tengo una reunión de ventas con [nombre / tipo de cliente].\n\nLo que vendo: [producto o servicio].\nLo que sé del cliente: [contexto].\n\nPrepárame: guion de apertura, 5 preguntas clave, objeciones probables con respuestas y un cierre claro."},"en":{"t":"Prepare a sales meeting","d":"Get a script with key questions and expected objections.","p":"I have a sales meeting with [name / type of client].\n\nWhat I sell: [product or service].\nWhat I know about the client: [context].\n\nPrepare: opening script, 5 key questions, likely objections with answers and a clear close."}},{"id":"seguimiento","area":"clientes","es":{"t":"Hacer seguimiento a prospectos","d":"Mensajes de seguimiento que reactivan conversaciones sin sonar insistente.","p":"Necesito hacer seguimiento a un prospecto que no responde hace [días/semanas].\n\nContexto: [última conversación].\nMi tono: [cercano / formal].\n\nEscríbeme 3 mensajes distintos: uno breve, uno con valor agregado y uno de última llamada."},"en":{"t":"Follow up with prospects","d":"Follow-up messages that revive conversations without sounding pushy.","p":"I need to follow up with a prospect who hasn’t replied in [days/weeks].\n\nContext: [last conversation].\nMy tone: [friendly / formal].\n\nWrite 3 different messages: one short, one adding value and one final call."}},{"id":"llamada-fria","area":"clientes","es":{"t":"Crear guion de llamada en frío","d":"Guion claro de 60 segundos para abrir conversaciones nuevas.","p":"Crea un guion de llamada en frío de 60 segundos.\n\nVendo: [producto o servicio].\nLlamo a: [tipo de cliente].\nEl dolor que resuelvo: [problema].\n\nIncluye: apertura, pregunta gancho, propuesta breve y cierre para agendar."},"en":{"t":"Create a cold-call script","d":"A clear 60-second script to open new conversations.","p":"Create a 60-second cold-call script.\n\nI sell: [product or service].\nI’m calling: [type of client].\nThe pain I solve: [problem].\n\nInclude: opener, hook question, short pitch and a scheduling close."}},{"id":"email-frio","area":"clientes","es":{"t":"Escribir email de venta en frío","d":"Email corto que abre conversaciones sin parecer spam.","p":"Escribe un email de venta en frío.\n\nVendo: [producto o servicio].\nDestinatario: [cargo / industria].\nBeneficio principal: [resultado concreto].\n\nMáximo 120 palabras, asunto llamativo y un solo llamado a la acción."},"en":{"t":"Write a cold sales email","d":"A short email that opens conversations without feeling like spam.","p":"Write a cold sales email.\n\nI sell: [product or service].\nRecipient: [role / industry].\nMain benefit: [concrete result].\n\nMax 120 words, catchy subject line and a single call to action."}},{"id":"venta-perdida","area":"clientes","es":{"t":"Analizar por qué perdí una venta","d":"Diagnóstico claro y acciones concretas para no perder ventas similares.","p":"Perdí una venta y quiero entender por qué.\n\nContexto: [resumen del proceso].\nObjeciones que surgieron: [lista].\nCompetencia: [si aplica].\n\nDame: diagnóstico probable, 3 señales que ignoré y qué cambiar en la próxima oportunidad."},"en":{"t":"Analyze why I lost a sale","d":"A clear diagnosis and concrete actions to avoid losing similar deals.","p":"I lost a sale and want to understand why.\n\nContext: [process summary].\nObjections raised: [list].\nCompetition: [if any].\n\nGive me: likely diagnosis, 3 signals I missed and what to change next time."}},{"id":"calendario","area":"marketing","es":{"t":"Armar calendario de contenido","d":"Un mes de contenido alineado a tus objetivos, listo para producir.","p":"Arma un calendario de contenido de 4 semanas.\n\nMi negocio: [descripción].\nCanales: [Instagram / LinkedIn / blog...].\nObjetivo del mes: [ventas / awareness / comunidad].\n\nPor pieza: fecha, canal, formato, tema y gancho."},"en":{"t":"Build a content calendar","d":"A month of content aligned to your goals, ready to produce.","p":"Build a 4-week content calendar.\n\nMy business: [description].\nChannels: [Instagram / LinkedIn / blog...].\nGoal for the month: [sales / awareness / community].\n\nPer piece: date, channel, format, topic and hook."}},{"id":"campana","area":"marketing","es":{"t":"Lanzar una campaña completa","d":"Copies, piezas y secuencia de correos de una sola vez.","p":"Quiero lanzar una campaña para [producto / oferta].\n\nAudiencia: [quién].\nPresupuesto: [monto o \"orgánico\"].\nDuración: [semanas].\n\nEntrega: mensaje central, 5 copies para anuncios, 3 correos de secuencia y el plan de publicación."},"en":{"t":"Launch a full campaign","d":"Copy, assets and an email sequence in one pass.","p":"I want to launch a campaign for [product / offer].\n\nAudience: [who].\nBudget: [amount or \"organic\"].\nDuration: [weeks].\n\nDeliver: core message, 5 ad copies, a 3-email sequence and the publishing plan."}},{"id":"reporte-campanas","area":"marketing","es":{"t":"Analizar resultados de campañas","d":"Lee tus métricas y te dice qué escalar y qué apagar.","p":"Analiza los resultados de mis campañas.\n\nPego las métricas: [datos o CSV].\nMi objetivo era: [meta].\n\nDime: qué funcionó, qué apagar, qué escalar y 3 hipótesis para probar la próxima semana."},"en":{"t":"Analyze campaign results","d":"Reads your metrics and tells you what to scale and what to kill.","p":"Analyze my campaign results.\n\nHere are the metrics: [data or CSV].\nMy goal was: [target].\n\nTell me: what worked, what to kill, what to scale and 3 hypotheses to test next week."}},{"id":"faq-clientes","area":"atencion","es":{"t":"Responder preguntas frecuentes","d":"Respuestas listas en tu tono para las dudas de siempre.","p":"Estas son las 10 preguntas que más me hacen los clientes: [lista].\n\nMi tono: [cercano / formal].\nMi negocio: [descripción].\n\nEscribe una respuesta modelo para cada una, breve y en mi voz."},"en":{"t":"Answer frequent questions","d":"Ready-made answers in your tone for the usual questions.","p":"These are the 10 questions clients ask me most: [list].\n\nMy tone: [friendly / formal].\nMy business: [description].\n\nWrite a model answer for each one, short and in my voice."}},{"id":"cliente-molesto","area":"atencion","es":{"t":"Responder a un cliente molesto","d":"Baja la tensión, protege la relación y resuelve.","p":"Un cliente está molesto por: [motivo].\n\nSu mensaje: [pegar mensaje].\nLo que puedo ofrecer: [opciones reales].\n\nEscribe una respuesta que reconozca el problema, baje la tensión y proponga una solución concreta."},"en":{"t":"Reply to an upset customer","d":"Lower the tension, protect the relationship and resolve it.","p":"A customer is upset about: [reason].\n\nTheir message: [paste message].\nWhat I can offer: [real options].\n\nWrite a reply that acknowledges the problem, lowers the tension and proposes a concrete solution."}},{"id":"tickets-resumen","area":"atencion","es":{"t":"Resumir los tickets del día","d":"Qué se repite, qué urge y qué mejorar de fondo.","p":"Aquí están los tickets/conversaciones de hoy: [pegar].\n\nDame: temas que se repiten, casos urgentes, tono general de los clientes y 2 mejoras de fondo para reducir estos tickets."},"en":{"t":"Summarize today’s tickets","d":"What repeats, what’s urgent and what to fix at the root.","p":"Here are today’s tickets/conversations: [paste].\n\nGive me: recurring topics, urgent cases, overall customer tone and 2 root-cause fixes to reduce these tickets."}},{"id":"sop","area":"operaciones","es":{"t":"Documentar un proceso (SOP)","d":"Convierte lo que haces de memoria en un manual paso a paso.","p":"Quiero documentar este proceso: [nombre].\n\nAsí lo hago hoy: [describir pasos como salgan].\n\nConviértelo en un SOP claro: objetivo, responsable, pasos numerados, herramientas y errores comunes."},"en":{"t":"Document a process (SOP)","d":"Turn what you do from memory into a step-by-step manual.","p":"I want to document this process: [name].\n\nThis is how I do it today: [describe steps roughly].\n\nTurn it into a clear SOP: goal, owner, numbered steps, tools and common mistakes."}},{"id":"reporte-semanal","area":"operaciones","es":{"t":"Automatizar el reporte semanal","d":"Un script que arma el reporte solo, cada semana.","p":"Quiero automatizar mi reporte semanal.\n\nDatos que uso: [fuentes: hojas de cálculo / sistema].\nLo que debe mostrar: [métricas].\nFormato: [correo / PDF / hoja].\n\nConstruye la herramienta y explícame cómo correrla cada lunes."},"en":{"t":"Automate the weekly report","d":"A script that builds the report by itself, every week.","p":"I want to automate my weekly report.\n\nData sources: [spreadsheets / system].\nWhat it must show: [metrics].\nFormat: [email / PDF / sheet].\n\nBuild the tool and explain how to run it every Monday."}},{"id":"organizar-carpetas","area":"operaciones","es":{"t":"Ordenar y clasificar archivos","d":"Limpia carpetas desordenadas y les pone reglas.","p":"Mi carpeta [ruta] es un desorden.\n\nContiene: [tipos de archivos].\nQuiero organizarla por: [cliente / fecha / tipo].\n\nPropón la estructura, muéveme los archivos y deja una regla clara para lo nuevo."},"en":{"t":"Sort and organize files","d":"Cleans messy folders and gives them rules.","p":"My folder [path] is a mess.\n\nIt contains: [file types].\nI want it organized by: [client / date / type].\n\nPropose the structure, move the files and leave a clear rule for new ones."}},{"id":"job-post","area":"rrhh","es":{"t":"Escribir una oferta de empleo","d":"Descripción del cargo que atrae al perfil correcto.","p":"Necesito publicar una vacante.\n\nCargo: [nombre].\nResponsabilidades: [lista].\nMi empresa: [descripción breve].\nRango salarial: [opcional].\n\nEscribe la oferta: título atractivo, misión del rol, responsabilidades, requisitos y beneficios."},"en":{"t":"Write a job posting","d":"A role description that attracts the right profile.","p":"I need to post a job opening.\n\nRole: [name].\nResponsibilities: [list].\nMy company: [short description].\nSalary range: [optional].\n\nWrite the posting: attractive title, role mission, responsibilities, requirements and benefits."}},{"id":"onboarding","area":"rrhh","es":{"t":"Crear plan de onboarding","d":"Los primeros 30 días de un empleado nuevo, organizados.","p":"Crea el plan de onboarding para: [cargo].\n\nMi empresa hace: [descripción].\nHerramientas que usamos: [lista].\n\nOrganiza los primeros 30 días: semana a semana, con objetivos, accesos y a quién conocer."},"en":{"t":"Create an onboarding plan","d":"A new hire’s first 30 days, organized.","p":"Create the onboarding plan for: [role].\n\nMy company does: [description].\nTools we use: [list].\n\nOrganize the first 30 days: week by week, with goals, access and who to meet."}},{"id":"flujo-caja","area":"finanzas","es":{"t":"Analizar el flujo de caja","d":"Entiende a dónde se va la plata y qué viene.","p":"Analiza mi flujo de caja.\n\nPego los movimientos: [datos / CSV].\nPeriodo: [rango].\n\nDame: entradas vs salidas por categoría, gastos que crecen, meses de riesgo y 3 acciones para mejorar la caja."},"en":{"t":"Analyze cash flow","d":"Understand where the money goes and what’s coming.","p":"Analyze my cash flow.\n\nHere are the transactions: [data / CSV].\nPeriod: [range].\n\nGive me: inflows vs outflows by category, growing expenses, risky months and 3 actions to improve cash."}},{"id":"cotizador","area":"finanzas","es":{"t":"Construir un cotizador","d":"Una herramienta que arma cotizaciones con tus precios y reglas.","p":"Construye un cotizador para mi negocio.\n\nVendo: [productos/servicios con precios].\nReglas: [descuentos, mínimos, extras].\nSalida: [PDF / correo listo para enviar].\n\nHazlo simple de usar: yo pongo los datos del cliente y me devuelve la cotización lista."},"en":{"t":"Build a quoting tool","d":"A tool that builds quotes with your prices and rules.","p":"Build a quoting tool for my business.\n\nI sell: [products/services with prices].\nRules: [discounts, minimums, extras].\nOutput: [PDF / ready-to-send email].\n\nMake it simple: I enter the client’s details and it returns a ready quote."}},{"id":"contrato","area":"legal","es":{"t":"Redactar un contrato de servicios","d":"Borrador claro para revisar con tu abogado.","p":"Redacta un borrador de contrato de servicios.\n\nServicio: [qué haré].\nPartes: [mi empresa] y [cliente].\nCondiciones clave: [pago, plazos, entregables].\n\nIncluye: alcance, pagos, confidencialidad, propiedad del trabajo y terminación. Nota: es un borrador para revisión legal."},"en":{"t":"Draft a services contract","d":"A clear draft to review with your lawyer.","p":"Draft a services contract.\n\nService: [what I’ll do].\nParties: [my company] and [client].\nKey terms: [payment, deadlines, deliverables].\n\nInclude: scope, payments, confidentiality, work ownership and termination. Note: this is a draft for legal review."}},{"id":"revisar-contrato","area":"legal","es":{"t":"Revisar un contrato antes de firmar","d":"Encuentra cláusulas riesgosas y te las explica en simple.","p":"Revisa este contrato antes de que lo firme: [pegar o adjuntar].\n\nYo soy: [parte que firma].\nMe preocupa: [pagos / exclusividad / responsabilidad].\n\nSeñala cláusulas riesgosas, explícalas en lenguaje simple y sugiere qué negociar."},"en":{"t":"Review a contract before signing","d":"Finds risky clauses and explains them in plain language.","p":"Review this contract before I sign it: [paste or attach].\n\nI am: [signing party].\nMy concerns: [payments / exclusivity / liability].\n\nFlag risky clauses, explain them in plain language and suggest what to negotiate."}},{"id":"fichas-producto","area":"ecommerce","es":{"t":"Escribir fichas de producto","d":"Descripciones que venden y posicionan en buscadores.","p":"Escribe las fichas de estos productos: [lista con datos básicos].\n\nMi tienda: [descripción y tono].\nCliente típico: [quién compra].\n\nPor producto: título SEO, descripción persuasiva, bullets de beneficios y meta description."},"en":{"t":"Write product listings","d":"Descriptions that sell and rank in search.","p":"Write listings for these products: [list with basic data].\n\nMy store: [description and tone].\nTypical customer: [who buys].\n\nPer product: SEO title, persuasive description, benefit bullets and meta description."}},{"id":"inventario","area":"ecommerce","es":{"t":"Montar control de inventario","d":"Una herramienta que avisa antes de que algo se agote.","p":"Construye un control de inventario simple.\n\nMis productos: [fuente: hoja de cálculo / plataforma].\nQuiero: stock actual, alertas de mínimos y reporte semanal de rotación.\n\nHazlo para alguien no técnico: explícame cómo usarlo día a día."},"en":{"t":"Set up inventory control","d":"A tool that warns you before something runs out.","p":"Build a simple inventory control.\n\nMy products: [source: spreadsheet / platform].\nI want: current stock, low-stock alerts and a weekly rotation report.\n\nMake it non-technical: explain how to use it day to day."}},{"id":"dashboard","area":"software","es":{"t":"Construir un dashboard del negocio","d":"Tus números clave en una sola pantalla, siempre al día.","p":"Construye un dashboard para mi negocio.\n\nFuentes de datos: [hojas / sistemas].\nMétricas clave: [ventas, caja, clientes...].\nQuién lo ve: [yo / equipo].\n\nHazlo claro y visual, y explícame cómo se actualiza."},"en":{"t":"Build a business dashboard","d":"Your key numbers on one screen, always up to date.","p":"Build a dashboard for my business.\n\nData sources: [sheets / systems].\nKey metrics: [sales, cash, customers...].\nWho sees it: [me / team].\n\nMake it clear and visual, and explain how it updates."}},{"id":"portal-clientes","area":"software","es":{"t":"Crear un portal para clientes","d":"Un lugar donde tus clientes ven avances, archivos y estados.","p":"Crea un portal simple para mis clientes.\n\nDeben poder ver: [avances / archivos / facturas].\nMis clientes son: [tipo].\nAcceso: [link privado / clave].\n\nConstrúyelo paso a paso y dime cómo darle acceso a cada cliente."},"en":{"t":"Create a client portal","d":"A place where clients see progress, files and statuses.","p":"Create a simple portal for my clients.\n\nThey should see: [progress / files / invoices].\nMy clients are: [type].\nAccess: [private link / password].\n\nBuild it step by step and tell me how to grant each client access."}},{"id":"plan-trimestre","area":"direccion","es":{"t":"Planear el próximo trimestre","d":"Convierte tus metas en un plan con dueños y fechas.","p":"Ayúdame a planear el próximo trimestre.\n\nMi negocio: [descripción].\nResultados del trimestre pasado: [resumen].\nMetas: [3 objetivos].\n\nEntrega: prioridades, iniciativas por meta, responsable sugerido y qué NO hacer este trimestre."},"en":{"t":"Plan next quarter","d":"Turn your goals into a plan with owners and dates.","p":"Help me plan next quarter.\n\nMy business: [description].\nLast quarter’s results: [summary].\nGoals: [3 objectives].\n\nDeliver: priorities, initiatives per goal, suggested owner and what NOT to do this quarter."}},{"id":"decision","area":"direccion","es":{"t":"Pensar una decisión difícil","d":"Un segundo cerebro que te muestra ángulos que no viste.","p":"Tengo que tomar una decisión difícil: [describirla].\n\nOpciones que veo: [A, B, C].\nLo que me preocupa: [riesgos].\n\nAyúdame: pros y contras reales, riesgos que no estoy viendo, qué haría falta para decidir con datos y tu recomendación con argumentos."},"en":{"t":"Think through a hard decision","d":"A second brain that shows you angles you missed.","p":"I have a hard decision to make: [describe it].\n\nOptions I see: [A, B, C].\nWhat worries me: [risks].\n\nHelp me: real pros and cons, risks I’m not seeing, what data would settle it and your recommendation with reasoning."}},{"id":"cambiar-ia","area":"continuidad","es":{"t":"Retomar un proyecto sin repetir contexto","d":"Conserva los avances, decisiones y próximos pasos para volver al trabajo con claridad.","p":"Estoy trabajando en: [proyecto o tarea].\n\nAyúdame a mantener un resumen actualizado con el objetivo, los avances, las decisiones tomadas y los próximos pasos. Cuando retome el trabajo, usa este contexto y pregúntame si falta algún dato. No cambies las decisiones registradas sin consultarme."},"en":{"t":"Resume a project so you can pick it back up","d":"Keep progress, decisions, and next steps clear for when you return to the work.","p":"I'm working on: [project or task].\n\nHelp me keep an up-to-date summary of the goal, progress, decisions made, and next steps. When I return to the work, use this context and ask me if anything is missing. Don't change recorded decisions without checking with me."}},{"id":"memoria-empresa","area":"continuidad","es":{"t":"Enseñarle tu empresa a la IA","d":"Una memoria que evita repetir el contexto en cada chat.","p":"Quiero que aprendas mi empresa de una vez.\n\nQué hacemos: [descripción].\nNuestro tono: [cómo escribimos].\nClientes: [tipos].\nReglas: [qué nunca hacer].\n\nGuarda esto como memoria del espacio y úsalo en todo lo que trabajemos aquí."},"en":{"t":"Teach the AI your business","d":"A memory that avoids repeating context in every chat.","p":"I want you to learn my business once.\n\nWhat we do: [description].\nOur tone: [how we write].\nClients: [types].\nRules: [what never to do].\n\nSave this as the workspace memory and use it in everything we do here."}},{"id":"market-001","area":"market","es":{"t":"Auditar mi negocio local","d":"Revisa cómo aparece tu negocio en Google Maps, qué dicen tus reseñas y cómo te comparas con los negocios cercanos.","p":"Quiero una auditoría de cómo aparece mi negocio en Google Maps.\n\nNegocio: [nombre exacto, como aparece en Google].\nCiudad y país: [por ejemplo: Doral, Florida, EE. UU. / Medellín, Colombia].\nRubro: [restaurante / clínica dental / salón de belleza / taller / otro].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca mi negocio en Google Maps y lee sus reseñas más recientes. Dame:\n1. Cómo aparece mi ficha: dirección, teléfono, sitio web, horarios y calificación.\n2. Qué elogian y de qué se quejan mis clientes en las reseñas.\n3. Los negocios cercanos de mi rubro mejor calificados y cómo me comparo en calificación y cantidad de reseñas.\n4. Cinco acciones concretas para mejorar mi presencia y mis reseñas.\n\nSi un dato no aparece en Google Maps, dímelo en vez de suponerlo."},"en":{"t":"Audit my local business","d":"Reviews how your business shows up on Google Maps, what your reviews say, and how you compare with nearby businesses.","p":"I want an audit of how my business shows up on Google Maps.\n\nBusiness: [exact name, as it appears on Google].\nCity and country: [for example: Doral, Florida, USA / Medellín, Colombia].\nType of business: [restaurant / dental clinic / beauty salon / auto shop / other].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Look up my business on Google Maps and read its most recent reviews. Give me:\n1. How my listing appears: address, phone, website, hours, and rating.\n2. What my customers praise and complain about in the reviews.\n3. The best-rated nearby businesses of my type and how I compare on rating and number of reviews.\n4. Five concrete actions to improve my presence and my reviews.\n\nIf something doesn't appear on Google Maps, tell me instead of guessing."}},{"id":"market-002","area":"market","es":{"t":"Competidores cerca de mi negocio","d":"Encuentra a tus competidores de la zona en Google Maps y te muestra quién aparece primero en Google cuando buscan tu servicio.","p":"Quiero conocer a mis competidores cercanos.\n\nMi negocio: [qué vendes o qué servicio das].\nZona: [barrio o ciudad, y país — por ejemplo: Houston, Texas, EE. UU. / Chapinero, Bogotá, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la zona, el país o el idioma, pregúntamelos antes de buscar. Busca en Google Maps los negocios de mi rubro en esa zona y arma una tabla con: nombre, dirección, teléfono, sitio web, calificación y número de reseñas. Después busca en Google mi servicio en esa zona (por ejemplo, \"dentista en Houston\") y dime quiénes aparecen primero, qué destacan en esos resultados y qué oportunidades tengo para diferenciarme.\n\nNo inventes precios ni datos que no aparezcan en los resultados."},"en":{"t":"Competitors near my business","d":"Finds your local competitors on Google Maps and shows who comes up first on Google when people search for your service.","p":"I want to know my nearby competitors.\n\nMy business: [what you sell or what service you offer].\nArea: [neighborhood or city, and country — for example: Houston, Texas, USA / Chapinero, Bogotá, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf the area, the country, or the language is missing, ask me before searching. Search Google Maps for businesses like mine in that area and build a table with: name, address, phone, website, rating, and number of reviews. Then search Google for my service in that area (for example, \"dentist in Houston\") and tell me who comes up first, what they highlight in those results, and what opportunities I have to stand out.\n\nDon't make up prices or details that don't appear in the results."}},{"id":"market-003","area":"market","es":{"t":"Ver los anuncios de la competencia","d":"Revisa los anuncios públicos de tus competidores y te resume qué mensajes y ofertas están usando.","p":"Quiero ver qué anuncios están publicando mis competidores.\n\nCompetidores: [nombre de la marca o su sitio web, de 1 a 3].\nPaís donde anuncian: [por ejemplo: Estados Unidos / México / Colombia].\nMi producto o servicio: [describir].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país o el idioma, pregúntamelos antes de buscar. Busca en las bibliotecas públicas de anuncios que tengas disponibles los anuncios activos de cada competidor. De los anuncios de Facebook e Instagram, resume: mensajes principales, ofertas y precios que mencionan, llamados a la acción, desde cuándo están activos y qué formato usan (imagen, video o texto). De los anuncios de Google solo se sabe que se mostraron y cuándo: dime cuántos encontraste y desde cuándo se muestran, sin inventar su texto. Termina con ideas para mi próxima campaña.\n\nNo copies los anuncios tal cual. Si no encuentras anuncios de una marca, dímelo."},"en":{"t":"See competitors' ads","d":"Reviews your competitors' public ads and sums up the messages and offers they're using.","p":"I want to see what ads my competitors are running.\n\nCompetitors: [brand name or website, 1 to 3].\nCountry where they advertise: [for example: United States / Mexico / Colombia].\nMy product or service: [describe].\nLanguage for the answer: [English / Spanish].\n\nIf the country or the language is missing, ask me before searching. Search the public ad libraries you have available for each competitor's active ads. For Facebook and Instagram ads, sum up: main messages, offers and prices they mention, calls to action, how long they've been running, and the format they use (image, video, or text). For Google ads, all that's known is that they were shown and when: tell me how many you found and since when they've been running, without making up their text. Finish with ideas for my next campaign.\n\nDon't copy the ads word for word. If you can't find ads for a brand, tell me."}},{"id":"market-004","area":"market","es":{"t":"Comparar precios online","d":"Busca productos parecidos al tuyo en tiendas online de EE. UU., México, Colombia, Chile, Argentina y Brasil, y te arma una tabla de precios para comparar.","p":"Quiero comparar el precio de mi producto con lo que se vende en internet.\n\nProducto: [tipo, marca, tamaño o modelo].\nMi precio actual: [monto y moneda].\nCiudad y país: [Estados Unidos, México, Colombia, Chile, Argentina o Brasil — por ejemplo: Miami, EE. UU. / Ciudad de México / Bogotá, Colombia].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país o el idioma, pregúntamelos antes de buscar; si mi país no es uno de esos, avísame en vez de buscar. Busca productos comparables en Google Shopping y arma una tabla con: producto, tienda, precio tal como aparece, calificación y número de reseñas si los hay, y si mencionan envío. Después dame el rango de precios (bajo, medio y alto), dónde queda mi precio y una recomendación.\n\nUsa solo los precios que encuentres; no los estimes."},"en":{"t":"Compare prices online","d":"Finds products like yours in online stores in the US, Mexico, Colombia, Chile, Argentina, and Brazil, and builds a price table to compare.","p":"I want to compare my product's price with what's sold online.\n\nProduct: [type, brand, size, or model].\nMy current price: [amount and currency].\nCity and country: [United States, Mexico, Colombia, Chile, Argentina, or Brazil — for example: Miami, USA / Mexico City / Bogotá, Colombia].\nLanguage for the answer: [English / Spanish].\n\nIf the country or the language is missing, ask me before searching; if my country isn't one of those, tell me instead of searching. Search Google Shopping for comparable products and build a table with: product, store, price as listed, rating and number of reviews if available, and whether they mention shipping. Then give me the price range (low, mid, and high), where my price falls, and a recommendation.\n\nOnly use prices you actually find; don't estimate them."}},{"id":"market-005","area":"market","es":{"t":"Detectar tendencias de mercado","d":"Compara qué tan buscados son varios temas o productos en Google y cómo cambia el interés con el tiempo.","p":"Quiero saber qué está creciendo en mi mercado.\n\nTemas o productos a comparar: [hasta 5 — por ejemplo: pilates, yoga, crossfit].\nPaís: [por ejemplo: Estados Unidos / Colombia / Argentina — o todo el mundo].\nPeriodo: [último mes / últimos 3 meses / último año / últimos 5 años].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país, el periodo o el idioma, pregúntamelos antes de buscar. Usa Google Trends para comparar el interés de búsqueda en el tiempo y para ver las búsquedas relacionadas que más están subiendo. Dame: qué tema crece y cuál baja, en qué meses sube el interés, las búsquedas relacionadas que más crecen y tres ideas de producto, contenido o campaña para probar en los próximos 30 días.\n\nRecuerda que Google Trends muestra interés relativo (de 0 a 100), no cantidades de búsquedas."},"en":{"t":"Spot market trends","d":"Compares how much people search for several topics or products on Google and how interest changes over time.","p":"I want to know what's growing in my market.\n\nTopics or products to compare: [up to 5 — for example: pilates, yoga, crossfit].\nCountry: [for example: United States / Colombia / Argentina — or worldwide].\nTime range: [past month / past 3 months / past year / past 5 years].\nLanguage for the answer: [English / Spanish].\n\nIf the country, the time range, or the language is missing, ask me before searching. Use Google Trends to compare search interest over time and to see the related searches that are rising the most. Give me: which topic is growing and which is falling, the months when interest goes up, the fastest-rising related searches, and three product, content, or campaign ideas to test in the next 30 days.\n\nRemember that Google Trends shows relative interest (0 to 100), not the number of searches."}},{"id":"market-006","area":"market","es":{"t":"Reputación y noticias de mi negocio","d":"Busca noticias recientes sobre tu negocio o tu marca y te avisa si hay algo que pueda afectar tu reputación.","p":"Quiero revisar qué se publica sobre mi negocio en las noticias.\n\nNegocio o marca: [nombre exacto].\nPaís: [por ejemplo: Estados Unidos / Perú / Chile].\nPeriodo: [última semana / último mes / último año].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta el país, el periodo o el idioma, pregúntamelos antes de buscar. Busca noticias recientes sobre mi negocio y, si no hay, sobre mi rubro en mi ciudad. Si además puedes leer las reseñas de mi negocio, inclúyelas. Dame: las noticias más importantes con fecha, medio y enlace; si el tono es positivo, neutral o negativo; los riesgos que veas y una respuesta sugerida si hay algo delicado.\n\nSi no encuentras menciones, dímelo claramente."},"en":{"t":"My business's reputation and news","d":"Finds recent news about your business or brand and flags anything that could affect your reputation.","p":"I want to check what the news is saying about my business.\n\nBusiness or brand: [exact name].\nCountry: [for example: United States / Peru / Chile].\nTime range: [past week / past month / past year].\nLanguage for the answer: [English / Spanish].\n\nIf the country, the time range, or the language is missing, ask me before searching. Search for recent news about my business and, if there isn't any, about my industry in my city. If you can also read my business's reviews, include them. Give me: the most important stories with date, outlet, and link; whether the tone is positive, neutral, or negative; any risks you see; and a suggested response if something is sensitive.\n\nIf you don't find any mentions, tell me clearly."}},{"id":"market-007","area":"market","es":{"t":"Qué dicen Google y la IA de mi negocio","d":"Revisa cómo apareces en Google y qué responde la IA cuando alguien pregunta por tu negocio o tu rubro.","p":"Quiero saber cómo aparece mi negocio cuando alguien lo busca en Google o le pregunta a una inteligencia artificial.\n\nNegocio: [nombre].\nSitio web: [dirección, si tienes].\nCiudad y país: [por ejemplo: Orlando, Florida, EE. UU. / Guadalajara, México].\nPreguntas que haría un cliente: [de 1 a 3 — por ejemplo: \"mejor dentista en Orlando\", \"dónde comprar café de especialidad en Guadalajara\"].\nIdioma de la respuesta: [español / inglés].\n\nSi te falta la ciudad, el país o el idioma, pregúntamelos antes de buscar. Busca esas preguntas en Google y pregúntaselas también a la IA de TerminalSync. Dame: en qué posición aparezco en Google (o si no aparezco), qué competidores salen antes, qué dice de mí el resumen con IA de Google si aparece, qué responde la IA de TerminalSync y si me menciona, y cinco acciones concretas para aparecer más.\n\nNo supongas posiciones ni respuestas que no hayas visto."},"en":{"t":"What Google and AI say about my business","d":"Checks how you show up on Google and what TerminalSync's AI says when someone asks about your business or industry.","p":"I want to know how my business shows up when someone searches for it on Google or asks an AI assistant.\n\nBusiness: [name].\nWebsite: [address, if you have one].\nCity and country: [for example: Orlando, Florida, USA / Guadalajara, Mexico].\nQuestions a customer would ask: [1 to 3 — for example: \"best dentist in Orlando\", \"where to buy specialty coffee in Guadalajara\"].\nLanguage for the answer: [English / Spanish].\n\nIf the city, the country, or the language is missing, ask me before searching. Search those questions on Google and also ask TerminalSync's AI. Give me: where I appear on Google (or whether I show up at all), which competitors come up first, what Google's AI overview says about me if there is one, what TerminalSync's AI answers and whether it mentions me, and five concrete actions to show up more.\n\nDon't assume positions or answers you haven't seen."}}],"jobCategories":[{"id":"ventas","es":"Ventas","en":"Sales"},{"id":"marketing","es":"Marketing","en":"Marketing"},{"id":"operaciones","es":"Operaciones","en":"Operations"},{"id":"legal","es":"Legal","en":"Legal"},{"id":"alojamientos","es":"Alojamientos","en":"Rentals"},{"id":"software","es":"Software","en":"Software"}],"jobs":[{"id":"buscar-clientes","cat":"ventas","es":{"t":"Buscador de clientes potenciales","d":"Investiga tu mercado y te entrega una lista de prospectos calificados.","cad":"Cada lunes","rep":"Lista con contactos y por qué encajan, en tu carpeta de Ventas","steps":["Investiga empresas que encajan con tu cliente ideal","Filtra y califica según tus criterios","Prepara el primer mensaje sugerido para cada uno"]},"en":{"t":"Prospect finder","d":"Researches your market and delivers a list of qualified prospects.","cad":"Every Monday","rep":"A list with contacts and why they fit, in your Sales folder","steps":["Researches companies matching your ideal client","Filters and qualifies by your criteria","Drafts a suggested first message for each"]}},{"id":"propuestas-auto","cat":"ventas","es":{"t":"Preparador de propuestas","d":"Convierte los datos de un cliente en una propuesta lista para revisar.","cad":"Cuando se lo pidas","rep":"Propuesta en tu formato, avisa por WhatsApp al terminar","steps":["Lee la carpeta del cliente y el histórico","Arma la propuesta con tu plantilla y precios","Te la deja lista para revisar y enviar"]},"en":{"t":"Proposal builder","d":"Turns a client’s details into a proposal ready to review.","cad":"On demand","rep":"Proposal in your format, pings you on WhatsApp when done","steps":["Reads the client folder and history","Builds the proposal with your template and pricing","Leaves it ready to review and send"]}},{"id":"crm-aldia","cat":"ventas","es":{"t":"CRM siempre al día","d":"Registra cada interacción y te avisa qué seguimiento toca hoy.","cad":"Todos los días, 7:00 am","rep":"Resumen diario: qué se movió y a quién contactar","steps":["Revisa correos y conversaciones nuevas","Actualiza el estado de cada negocio","Prepara la lista de seguimientos del día"]},"en":{"t":"CRM always up to date","d":"Logs every interaction and tells you which follow-up is due today.","cad":"Daily, 7:00 am","rep":"Daily digest: what moved and who to contact","steps":["Reviews new emails and conversations","Updates each deal’s status","Prepares today’s follow-up list"]}},{"id":"seo-mensual","cat":"marketing","es":{"t":"Analista SEO mensual","d":"Revisa tu sitio y el de tus competidores y te dice dónde ganar.","cad":"El 1° de cada mes","rep":"Informe con hallazgos y 5 acciones priorizadas","steps":["Analiza posiciones, contenido y competidores","Detecta oportunidades y caídas","Prioriza qué publicar o corregir este mes"]},"en":{"t":"Monthly SEO analyst","d":"Reviews your site and competitors and tells you where to win.","cad":"1st of every month","rep":"Report with findings and 5 prioritized actions","steps":["Analyzes rankings, content and competitors","Spots opportunities and drops","Prioritizes what to publish or fix this month"]}},{"id":"contenido-semanal","cat":"marketing","es":{"t":"Productor de contenido","d":"Produce los borradores de la semana en tu voz, listos para aprobar.","cad":"Cada viernes","rep":"Piezas en tu carpeta de Marketing + aviso por Telegram","steps":["Lee tu calendario y temas del mes","Escribe posts, correos y guiones en tu tono","Deja todo en borradores para tu revisión"]},"en":{"t":"Content producer","d":"Produces the week’s drafts in your voice, ready to approve.","cad":"Every Friday","rep":"Pieces in your Marketing folder + Telegram ping","steps":["Reads your calendar and monthly topics","Writes posts, emails and scripts in your tone","Leaves everything as drafts for review"]}},{"id":"vigia-campanas","cat":"marketing","es":{"t":"Vigía de campañas","d":"Monitorea tus anuncios y te alerta antes de quemar presupuesto.","cad":"Todos los días","rep":"Alerta solo si algo se sale de rango; resumen semanal","steps":["Revisa métricas de cada campaña activa","Compara contra tus metas y costos máximos","Sugiere pausar, escalar o ajustar"]},"en":{"t":"Campaign watchdog","d":"Monitors your ads and alerts you before budget burns.","cad":"Daily","rep":"Alerts only if something drifts; weekly summary","steps":["Checks metrics on every active campaign","Compares against your targets and max costs","Suggests pausing, scaling or adjusting"]}},{"id":"reporte-lunes","cat":"operaciones","es":{"t":"Reportero de los lunes","d":"Arma el informe semanal del negocio sin que nadie lo persiga.","cad":"Cada lunes, 6:00 am","rep":"Informe en PDF + correo al equipo","steps":["Junta los datos de tus fuentes","Arma el informe con tu formato","Lo envía al equipo y te avisa"]},"en":{"t":"Monday reporter","d":"Builds the weekly business report without anyone chasing it.","cad":"Every Monday, 6:00 am","rep":"PDF report + email to the team","steps":["Gathers data from your sources","Builds the report in your format","Sends it to the team and pings you"]}},{"id":"clasificador","cat":"operaciones","es":{"t":"Clasificador de correos y documentos","d":"Ordena lo que llega: facturas, contratos, soporte, spam.","cad":"Cada hora","rep":"Todo archivado en su carpeta; urgentes a tu WhatsApp","steps":["Lee lo nuevo en el correo y las carpetas","Clasifica y archiva según tus reglas","Escala solo lo que necesita tu decisión"]},"en":{"t":"Email & document sorter","d":"Sorts what comes in: invoices, contracts, support, spam.","cad":"Hourly","rep":"Everything filed in its folder; urgent items to your WhatsApp","steps":["Reads new mail and folder drops","Classifies and files by your rules","Escalates only what needs your decision"]}},{"id":"pendientes","cat":"operaciones","es":{"t":"Monitor de pendientes","d":"Persigue las tareas vencidas para que nada se enfríe.","cad":"Todos los días, 5:00 pm","rep":"Lista de vencidos y quién los tiene, cada tarde","steps":["Revisa tareas y compromisos de cada espacio","Detecta lo vencido o a punto de vencer","Redacta los recordatorios para enviar"]},"en":{"t":"Overdue tracker","d":"Chases overdue tasks so nothing goes cold.","cad":"Daily, 5:00 pm","rep":"List of overdue items and owners, every afternoon","steps":["Reviews tasks and commitments in each space","Flags overdue and at-risk items","Drafts the reminders to send"]}},{"id":"revisor-contratos","cat":"legal","es":{"t":"Revisor de contratos","d":"Cada contrato nuevo llega revisado, con riesgos señalados en simple.","cad":"Cuando llega un contrato","rep":"Resumen de riesgos y qué negociar, antes de tu firma","steps":["Lee el contrato que llega a la carpeta","Señala cláusulas riesgosas y las explica","Prepara la lista de puntos a negociar"]},"en":{"t":"Contract reviewer","d":"Every new contract arrives reviewed, risks flagged in plain language.","cad":"When a contract arrives","rep":"Risk summary and negotiation points, before you sign","steps":["Reads contracts dropped in the folder","Flags risky clauses and explains them","Prepares the negotiation checklist"]}},{"id":"huespedes","cat":"alojamientos","es":{"t":"Anfitrión digital","d":"Procesa cada reserva: bienvenida, portería e ingreso registrado.","cad":"Con cada reserva","rep":"Todo registrado; te avisa solo si algo requiere tu decisión","steps":["Envía la bienvenida e instrucciones al huésped","Notifica a portería con los datos del ingreso","Registra la reserva y el pago en tu control"]},"en":{"t":"Digital host","d":"Handles each booking: welcome, front desk and logged check-in.","cad":"With every booking","rep":"Everything logged; pings you only if something needs your call","steps":["Sends the guest welcome and instructions","Notifies the front desk with check-in details","Logs the booking and payment in your tracker"]}},{"id":"guardian-bugs","cat":"software","es":{"t":"Guardián del código","d":"Revisa bugs reportados, corre pruebas y propone correcciones.","cad":"Cada noche","rep":"Resumen matutino: qué se arregló y qué espera tu OK","steps":["Revisa los bugs e issues nuevos","Corre las pruebas y reproduce errores","Propone la corrección y la deja lista para revisar"]},"en":{"t":"Code guardian","d":"Reviews reported bugs, runs tests and proposes fixes.","cad":"Every night","rep":"Morning digest: what was fixed and what awaits your OK","steps":["Reviews new bugs and issues","Runs tests and reproduces errors","Proposes the fix, ready for your review"]}}]} as const;
